description:
Buttons joined into one control: inner corners squared, shared borders overlapped.

  ButtonGroup(variant: :outline, aria_label: "Range") do
    Button { "Years" }
    Button { "Months" }
    Button { "Days" }
  end

`variant:`, `size:`, `icon:` and `disabled:` apply to every Button inside (a button's own variant / size wins; the group's `disabled:` can't be undone). Outlined variants overlap their borders into one hairline; filled ones keep a hairline gap.

examples.code:
phlex do
  ButtonGroup(variant:, size:, orientation:, disabled:, aria_label: "Range") do
    Button { "Years" }
    Button { "Months" }
    Button { "Days" }
  end
end

phlex do
  ButtonGroup(orientation: :vertical, variant: :outline) do
    Button { "Profile" }
    Button { "Billing" }
    Button { "Settings" }
  end
end

phlex do
  ButtonGroup(variant: :outline, icon: true, aria_label: "Text formatting") do
    Button(aria_label: "Bold") { Icon(:bold) }
    Button(aria_label: "Italic") { Icon(:italic) }
    Button(aria_label: "Underline") { Icon(:underline) }
  end
end

phlex do
  ButtonGroup(variant: :outline) do
    Button { "Save" }
    Button(icon: true, aria_label: "More save options") { Icon(:chevron_down) }
  end
end

phlex do
  ButtonGroup(dir: "rtl", variant: :outline) do
    Button { "سنوات" }
    Button { "أشهر" }
    Button { "أيام" }
  end
end
